/**
 * `fetch` compatibility shim for the Hindsight SDK (generated by
 * `@hey-api/openapi-ts`, which calls `fetch(Request)`).
 *
 * Node's undici mutates `init` when given a `Request` and needs `duplex` for a
 * streamed body; giving the shim the URL and a plain init sidesteps both. The
 * patch is process-wide but idempotent and marked, so a second copy of this
 * module — or a host path that never installs it — leaves one patch.
 *
 * @module omd-memory/client/fetch-compat
 */

const PATCH_MARKER: unique symbol = Symbol('omd-memory.fetch-request-compat')

type FetchWithMarker = typeof fetch & { [PATCH_MARKER]?: true }
type RequestInitWithDuplex = RequestInit & { duplex?: 'half' }

function isRequest(value: unknown): value is Request {
  return typeof Request !== 'undefined' && value instanceof Request
}

function requestToInit(request: Request): RequestInitWithDuplex {
  return {
    method: request.method,
    headers: request.headers,
    body: request.body,
    signal: request.signal,
    redirect: request.redirect,
    credentials: request.credentials,
    cache: request.cache,
    mode: request.mode,
    referrer: request.referrer,
    referrerPolicy: request.referrerPolicy,
    integrity: request.integrity,
    keepalive: request.keepalive,
    ...(request.body ? { duplex: 'half' as const } : {}),
  }
}

/**
 * Install the shim once per process. Safe to call from every client
 * construction: an already-patched or absent `fetch` returns immediately.
 */
export function installFetchRequestCompat(): void {
  const currentFetch = globalThis.fetch as FetchWithMarker | undefined
  if (!currentFetch || currentFetch[PATCH_MARKER]) return

  const originalFetch = currentFetch.bind(globalThis) as typeof fetch
  const patchedFetch: FetchWithMarker = ((input: RequestInfo | URL, init?: RequestInit) =>
    isRequest(input) ? originalFetch(input.url, { ...requestToInit(input), ...init }) : originalFetch(input, init)
  ) as FetchWithMarker
  patchedFetch[PATCH_MARKER] = true
  globalThis.fetch = patchedFetch
}
